/* ===================== BÀI 27 · Counter và đo xung ===================== */
/* Bài 27 · Counter và đo xung (AMTS-EMB-001-M07-L03, MC51-027) — sinh bởi tools/author/mcu8051/l27.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR27=[{"label":"Ví dụ: Đếm 5 sườn xuống ở chân T0","code":"; Ví dụ 1: Timer 0 đếm sự kiện: 5 sườn xuống ở chân T0 (P3.4)\n; Xung do chính chương trình tạo (giả lập cảm biến nối vào T0)\n        ORG     0000H\n        MOV     TMOD,#05H               ; Timer 0: C/T = 1, chế độ 1\n        SETB    TR0                     ; cho bộ đếm chạy\n        MOV     R7,#5\nXUNG:   CLR     P3.4                    ; sườn 1 -> 0: đếm thêm 1\n        NOP\n        SETB    P3.4                    ; trở về mức 1\n        DJNZ    R7,XUNG\n        MOV     A,TL0                   ; A = số sườn đã đếm\n        SJMP    $\n        END\n","note":"Mỗi vòng: CLR P3.4 (sườn xuống), NOP, SETB P3.4, DJNZ — 5 chu kỳ. TL0 tăng ở chu kỳ 7, 12, 17, 22, 27: chậm 2 chu kỳ sau lệnh CLR (một chu kỳ để lấy mẫu thấy 0, một chu kỳ để tăng). Cuối cùng A = TL0 = 05H, tổng 30 chu kỳ.","dev":{"led":true,"btn":true},"fosc":12000000},{"label":"Bẫy: Quên C/T = 1, đếm chu kỳ máy","code":"; Ví dụ 2 (bẫy): quên C/T = 1, Timer 0 đếm chu kỳ máy\n; Cùng chương trình ví dụ 1, chỉ khác TMOD = 01H\n        ORG     0000H\n        MOV     TMOD,#01H               ; SAI: C/T = 0 là bộ định thời\n        SETB    TR0\n        MOV     R7,#5\nXUNG:   CLR     P3.4\n        NOP\n        SETB    P3.4\n        DJNZ    R7,XUNG\n        MOV     A,TL0                   ; A = số chu kỳ máy, không phải 5\n        SJMP    $\n        END\n","note":"TMOD = 01H nên C/T = 0: Timer 0 đếm mọi chu kỳ máy từ chu kỳ 4 tới 30, tức 27 = 1BH, không liên quan tới số xung ở P3.4. Đổi lại TMOD = 05H để thấy A = 05H như ví dụ 1.","dev":{"led":true,"btn":true},"fosc":12000000},{"label":"Bẫy: Giữ chân ở 0 lâu vẫn chỉ đếm 1","code":"; Ví dụ 3 (bẫy): bộ đếm đếm SƯỜN xuống, không đếm thời gian\n; Chân T0 giữ mức 0 suốt 50 chu kỳ máy nhưng chỉ đếm 1\n        ORG     0000H\n        MOV     TMOD,#05H\n        SETB    TR0\n        CLR     P3.4                    ; sườn xuống: đếm 1\n        MOV     R7,#25\n        DJNZ    R7,$                    ; giữ mức 0: 25 x 2 = 50 chu kỳ\n        SETB    P3.4                    ; sườn lên: không đếm\n        MOV     A,TL0                   ; A = 01H\n        SJMP    $\n        END\n","note":"Chân T0 xuống 0 sau lệnh CLR ở chu kỳ 4 và ở mức 0 hơn 50 chu kỳ (DJNZ 25 lần × 2 chu kỳ) tới SETB ở chu kỳ 56. Bộ đếm chỉ đếm sườn 1→0 nên TL0 = 01H; sườn lên ở SETB P3.4 không được đếm. Muốn đo thời gian chân ở mức 0 thì dùng bộ định thời (GATE, Bài 25).","dev":{"led":true,"btn":true},"fosc":12000000},{"label":"Ví dụ: Đo tần số bằng cửa sổ 200 chu kỳ","code":"; Ví dụ 4: đo tần số: đếm xung trong cửa sổ 200 chu kỳ\n; Timer 1 (bộ định thời, chế độ 2) tạo cửa sổ; Timer 0 đếm\n        ORG     0000H\n        MOV     TMOD,#25H               ; T1: timer chế độ 2; T0: counter\n        MOV     TH1,#38H                ; 256 - 200 = 38H\n        MOV     TL1,#38H\n        SETB    TR0\n        SETB    TR1                     ; mở cửa sổ\nXUNG:   CLR     P3.4                    ; nguồn xung giả lập:\n        NOP                             ; mỗi xung 6 chu kỳ máy\n        NOP\n        SETB    P3.4\n        JNB     TF1,XUNG                ; hết 200 chu kỳ?\n        CLR     TR0                     ; đóng cửa sổ\n        CLR     TR1\n        MOV     A,TL0                   ; số xung trong cửa sổ\n        SJMP    $\n        END\n","note":"Timer 1 mở cửa sổ từ chu kỳ 9, TF1 bật ở chu kỳ 208 (200 nhịp). Vòng tạo xung dài 6 chu kỳ; vòng thứ 34 thấy TF1 và thoát. A = 22H = 34 xung, ước lượng 34 / 200 µs = 170 kHz so với 166,7 kHz thật: sai ±1 xung cộng phần cửa sổ của Timer 0 dài hơn.","dev":{"led":true,"btn":true},"fosc":12000000},{"label":"Bẫy: Đọc TL0 rồi TH0 khi timer đang chạy","code":"; Ví dụ 5 (bẫy): đọc TL0 rồi TH0 khi timer đang chạy\n; TL0 tràn sang TH0 giữa hai lệnh đọc: kết quả sai 256\n        ORG     0000H\n        MOV     TMOD,#01H\n        MOV     TH0,#00H\n        MOV     TL0,#0FEH\n        SETB    TR0\n        MOV     A,TL0                   ; đọc byte thấp\n        MOV     B,TH0                   ; đọc byte cao: TH0 đã tăng\n        CLR     TR0\n        SJMP    $\n        END\n","note":"TL0 bắt đầu FEH. MOV A,TL0 đọc FFH; trong 2 chu kỳ của MOV B,TH0, TL0 tràn và TH0 lên 01H, nên B = 01H. Ghép B:A = 01FFH, sai 256 so với giá trị thật lúc đọc (00FFH → 0100H).","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Đọc an toàn TH0, TL0, so lại TH0","code":"; Ví dụ 6: đọc an toàn: TH0, TL0, rồi so lại TH0\n; Nếu TH0 đổi trong lúc đọc thì đọc lại cả hai byte\n        ORG     0000H\n        MOV     TMOD,#01H\n        MOV     TH0,#00H\n        MOV     TL0,#0FEH\n        SETB    TR0\nDOC:    MOV     A,TH0                   ; byte cao\n        MOV     R6,TL0                  ; byte thấp\n        CJNE    A,TH0,DOC               ; TH0 đã đổi? đọc lại\n        CLR     TR0\n        SJMP    $\n        END\n","note":"Vòng DOC đọc TH0 (A = 00H), TL0, rồi CJNE thấy TH0 đã là 01H nên đọc lại. Lần hai A = 01H, R6 = 05H và TH0 không đổi: A:R6 = 0105H là một giá trị bộ đếm thật sự đã có. Tổng 18 chu kỳ.","dev":{"led":true},"fosc":12000000}];
const sim27=makeSim51(document.getElementById("m51-l27"),{id:"s27",presets:PR27,ram:256});
makeEx51(document.getElementById("ex-l27"),"l27",[{"t":"Bộ đếm báo sau K sự kiện","d":"<p>Ô <code>30H<\/code> chứa K (1 ≤ K ≤ 255; K = 0 nghĩa là 256). Hãy đặt <b>Timer 1 là bộ đếm sự kiện chế độ 2<\/b> (đếm sườn xuống ở chân T1 = P3.5) sao cho cờ TF1 bật sau đúng K sự kiện và cứ mỗi K sự kiện lại bật: nạp TH1 và TL1, <b>giữ nguyên nửa TMOD của Timer 0<\/b>, xóa cờ TF1 cũ, rồi cho chạy (TR1 = 1). Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: K = 10 → TH1 = TL1 = F6H, nửa cao TMOD = 0110B.<\/p>","start":"        ORG     0000H\n        MOV     TMOD,#20H               ; Timer 1 chế độ 2 (đếm gì?)\n        MOV     TH1,30H                 ; nạp K?\n        MOV     TL1,30H\n        SETB    TR1\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":10},"regs":{"TMOD":1,"TCON":0,"TH1":85,"TL1":85}},"expect":{"iram":{"0x30":10},"regs":{"TMOD":97,"TH1":246,"TL1":246},"bits":{"TR1":1,"TF1":0}}},{"setup":{"iram":{"0x30":1},"regs":{"TMOD":0,"TCON":0,"TH1":85,"TL1":85,"PSW":128}},"expect":{"iram":{"0x30":1},"regs":{"TMOD":96,"TH1":255,"TL1":255},"bits":{"TR1":1,"TF1":0}}},{"setup":{"iram":{"0x30":255},"regs":{"TMOD":2,"TCON":128,"TH1":85,"TL1":85}},"expect":{"iram":{"0x30":255},"regs":{"TMOD":98,"TH1":1,"TL1":1},"bits":{"TR1":1,"TF1":0}}},{"setup":{"iram":{"0x30":100},"regs":{"TMOD":5,"TCON":128,"TH1":85,"TL1":85}},"expect":{"iram":{"0x30":100},"regs":{"TMOD":101,"TH1":156,"TL1":156},"bits":{"TR1":1,"TF1":0}}},{"setup":{"iram":{"0x30":0},"regs":{"TMOD":1,"TCON":0,"TH1":85,"TL1":85}},"expect":{"iram":{"0x30":0},"regs":{"TMOD":97,"TH1":0,"TL1":0},"bits":{"TR1":1,"TF1":0}}},{"setup":{"iram":{"0x30":3},"regs":{"TMOD":13,"TCON":0,"TH1":85,"TL1":85}},"expect":{"iram":{"0x30":3},"regs":{"TMOD":109,"TH1":253,"TL1":253},"bits":{"TR1":1,"TF1":0}}},{"setup":{"iram":{"0x30":60},"regs":{"TMOD":33,"TCON":0,"TH1":85,"TL1":85}},"expect":{"iram":{"0x30":60},"regs":{"TMOD":97,"TH1":196,"TL1":196},"bits":{"TR1":1,"TF1":0}}}]},"hints":["Nửa Timer 1 của TMOD: GATE = 0, C/T = 1, M1 M0 = 10 → 0110B. Giữ nửa Timer 0 bằng ANL rồi ORL (Bài 25).","Chế độ 2 tràn sau 256 − TH1 sự kiện: nạp 256 − K = 0 − K vào cả TH1 (nạp lại) và TL1 (lần đầu).","Một số bộ thử có TF1 = 1 từ trước: CLR TF1 trước khi cho chạy."],"why":"Bộ đếm sự kiện khác bộ định thời đúng ở bit C/T; giá trị nạp tính như Bài 26 nhưng đơn vị là sự kiện chứ không phải chu kỳ máy. Test 7 có Timer 1 đang là bộ định thời: quên C/T = 1 sẽ đếm chu kỳ máy (ví dụ 2). Test 3, 4 có cờ TF1 cũ."},{"t":"Ghép số đếm 24 bit khi có tràn treo","d":"<p>Timer 0 là bộ đếm sự kiện chế độ 1, <b>đã dừng<\/b> (TR0 = 0). Chương trình chính dùng R7 làm byte thứ ba: mỗi lần thấy TF0 = 1 thì xóa cờ và tăng R7. Lúc này có thể còn <b>một lần tràn chưa được cộng<\/b> (TF0 = 1). Hãy ghép số đếm đầy đủ vào <code>30H<\/code> (byte cao), <code>31H<\/code>, <code>32H<\/code> (byte thấp), cập nhật R7 và để TF0 = 0. R7 ≤ FEH.<\/p><p>Ví dụ: R7 = 02H, TH0 = 34H, TL0 = 56H, TF0 = 0 → 30H = 02H, 31H = 34H, 32H = 56H.<\/p>","start":"        ORG     0000H\n        MOV     30H,R7                  ; byte thứ ba = số lần tràn đã ghi\n        MOV     31H,TH0\n        MOV     32H,TL0\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":238,"0x31":238,"0x32":238},"regs":{"TMOD":5,"TCON":0,"TH0":52,"TL0":86,"R7":2}},"expect":{"iram":{"0x30":2,"0x31":52,"0x32":86},"regs":{"R7":2,"TH0":52,"TL0":86},"bits":{"TF0":0}}},{"setup":{"iram":{"0x30":238,"0x31":238,"0x32":238},"regs":{"TMOD":5,"TCON":32,"TH0":0,"TL0":0,"R7":2}},"expect":{"iram":{"0x30":3,"0x31":0,"0x32":0},"regs":{"R7":3,"TH0":0,"TL0":0},"bits":{"TF0":0}}},{"setup":{"iram":{"0x30":238,"0x31":238,"0x32":238},"regs":{"TMOD":5,"TCON":0,"TH0":0,"TL0":5,"R7":0}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":5},"regs":{"R7":0,"TH0":0,"TL0":5},"bits":{"TF0":0}}},{"setup":{"iram":{"0x30":238,"0x31":238,"0x32":238},"regs":{"TMOD":5,"TCON":0,"TH0":255,"TL0":255,"R7":254}},"expect":{"iram":{"0x30":254,"0x31":255,"0x32":255},"regs":{"R7":254,"TH0":255,"TL0":255},"bits":{"TF0":0}}},{"setup":{"iram":{"0x30":238,"0x31":238,"0x32":238},"regs":{"TMOD":5,"TCON":32,"TH0":0,"TL0":0,"R7":0}},"expect":{"iram":{"0x30":1,"0x31":0,"0x32":0},"regs":{"R7":1,"TH0":0,"TL0":0},"bits":{"TF0":0}}},{"setup":{"iram":{"0x30":238,"0x31":238,"0x32":238},"regs":{"TMOD":5,"TCON":32,"TH0":128,"TL0":0,"R7":16}},"expect":{"iram":{"0x30":17,"0x31":128,"0x32":0},"regs":{"R7":17,"TH0":128,"TL0":0},"bits":{"TF0":0}}},{"setup":{"iram":{"0x30":238,"0x31":238,"0x32":238},"regs":{"TMOD":5,"TCON":32,"TH0":0,"TL0":1,"R7":7}},"expect":{"iram":{"0x30":8,"0x31":0,"0x32":1},"regs":{"R7":8,"TH0":0,"TL0":1},"bits":{"TF0":0}}}]},"hints":["Khi TF0 = 1, TH0:TL0 đã quay về 0000H và đếm tiếp: lần tràn đó chưa nằm trong R7.","JNB TF0,… để bỏ qua; nếu cờ bật thì CLR TF0 và INC R7, rồi chép R7, TH0, TL0."],"why":"Số đếm thật = R7 × 65 536 + TH0:TL0, nhưng R7 chỉ đúng khi mọi lần tràn đã được cộng. Bỏ qua tràn treo làm thiếu đúng 65 536 sự kiện (test 2, 5, 6, 7). Ở Chương 8 việc cộng R7 chuyển vào chương trình ngắt Timer 0."},{"t":"Tạo N xung nhanh nhất cho bộ đếm","d":"<p>Bộ chấm cho <b>Timer 0 đếm sự kiện chế độ 1 đang chạy<\/b> (TMOD = 05H, TR0 = 1, TH0:TL0 = 0000H). Ô <code>30H<\/code> chứa N (1 ≤ N ≤ 255). Hãy tạo <b>đúng N sườn xuống<\/b> ở chân T0 (P3.4) để bộ đếm đếm được TL0 = N, kết thúc với P3 = FFH (không đổi chân khác). Yêu cầu tối ưu: không quá <b>4N + 4 chu kỳ máy<\/b> (bộ chấm kiểm ở N = 255: ≤ 1024 chu kỳ) và mã không quá <b>12 byte<\/b>.<\/p><p>Ví dụ: N = 5 → TL0 = 05H, P3 = FFH.<\/p>","start":"        ORG     0000H\n        MOV     R7,30H                  ; N xung\nLAP:    ACALL   XUNG                    ; tạo 1 xung\n        DJNZ    R7,LAP\n        SJMP    $\nXUNG:   CPL     P3.4                    ; 1 -> 0: sườn xuống\n        NOP\n        CPL     P3.4                    ; 0 -> 1\n        RET\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":5},"regs":{"TMOD":5,"TCON":16,"TH0":0,"TL0":0}},"expect":{"regs":{"TH0":0,"TL0":5,"TMOD":5},"ports":{"P3":255},"bits":{"TR0":1}}},{"setup":{"iram":{"0x30":1},"regs":{"TMOD":5,"TCON":16,"TH0":0,"TL0":0}},"expect":{"regs":{"TH0":0,"TL0":1,"TMOD":5},"ports":{"P3":255},"bits":{"TR0":1}}},{"setup":{"iram":{"0x30":255},"regs":{"TMOD":5,"TCON":16,"TH0":0,"TL0":0}},"expect":{"regs":{"TH0":0,"TL0":255,"TMOD":5},"ports":{"P3":255},"bits":{"TR0":1}}},{"setup":{"iram":{"0x30":100},"regs":{"TMOD":5,"TCON":16,"TH0":0,"TL0":0}},"expect":{"regs":{"TH0":0,"TL0":100,"TMOD":5},"ports":{"P3":255},"bits":{"TR0":1}}},{"setup":{"iram":{"0x30":128},"regs":{"TMOD":5,"TCON":16,"TH0":0,"TL0":0}},"expect":{"regs":{"TH0":0,"TL0":128,"TMOD":5},"ports":{"P3":255},"bits":{"TR0":1}}},{"setup":{"iram":{"0x30":37},"regs":{"TMOD":5,"TCON":16,"TH0":0,"TL0":0}},"expect":{"regs":{"TH0":0,"TL0":37,"TMOD":5},"ports":{"P3":255},"bits":{"TR0":1}}},{"setup":{"iram":{"0x30":2},"regs":{"TMOD":5,"TCON":16,"TH0":0,"TL0":0}},"expect":{"regs":{"TH0":0,"TL0":2,"TMOD":5},"ports":{"P3":255},"bits":{"TR0":1}}}],"maxCyc":1024,"maxBytes":12},"hints":["Bộ đếm nhận một sườn khi chân ở mức 1 tại một lần lấy mẫu và mức 0 ở lần lấy mẫu sau; mỗi mức chỉ cần giữ một chu kỳ máy.","CLR P3.4 rồi SETB P3.4 liền nhau đã cho một xung hợp lệ (mức 0 đúng 1 chu kỳ). Vòng DJNZ thêm 2 chu kỳ.","Code mẫu đếm đúng nhưng mỗi xung tốn 9 chu kỳ (ACALL, NOP, RET) và mã dài 14 byte: đưa phần tạo xung vào thẳng vòng lặp."],"why":"Tốc độ đếm tối đa của T0/T1 là f_osc/24 (một xung mỗi 2 chu kỳ máy) vì cần hai lần lấy mẫu cho một sườn. Vòng CLR, SETB, DJNZ cho 4 chu kỳ mỗi xung, 10 byte: 2 + 4N + 2 chu kỳ. Nếu viết SETB trước CLR thì chân kết thúc ở 0 (P3 = EFH)."}]);

makeQuiz("quiz27","score27",[{"q": "Thạch anh 12 MHz. Tần số xung lớn nhất mà Timer 0 ở chế độ đếm sự kiện còn đếm đủ là bao nhiêu?", "o": ["1 MHz (f_osc/12)", "12 MHz", "6 MHz (f_osc/2)", "500 kHz (f_osc/24)"], "a": 3, "e": "Một sườn cần hai lần lấy mẫu ở hai chu kỳ máy liên tiếp (mẫu 1 rồi mẫu 0), nên mỗi xung ít nhất 2 chu kỳ máy = 24 chu kỳ thạch anh: 12 MHz / 24 = 500 kHz."}, {"q": "Cần Timer 1 là bộ định thời chế độ 2 (tạo cửa sổ) và Timer 0 là bộ đếm sự kiện chế độ 1. TMOD bằng bao nhiêu?", "o": ["52H", "25H", "21H", "15H"], "a": 1, "e": "Nửa cao (Timer 1): GATE 0, C/T 0, M1M0 10 → 0010B = 2. Nửa thấp (Timer 0): GATE 0, C/T 1, M1M0 01 → 0101B = 5. TMOD = 25H (ví dụ 4)."}, {"q": "Chân T0 xuống 0 rồi giữ ở 0 trong 50 chu kỳ máy, sau đó lên 1. Bộ đếm Timer 0 (C/T = 1) tăng bao nhiêu?", "o": ["50", "0", "1", "2"], "a": 2, "e": "Bộ đếm đếm sườn 1→0, không đếm thời gian ở mức 0 và không đếm sườn lên (ví dụ 3)."}, {"q": "Timer 1 ở chế độ 2 đếm sự kiện, TH1 = TL1 = F6H. Sau bao nhiêu sự kiện thì TF1 bật lần đầu?", "o": ["246", "10", "9", "256"], "a": 1, "e": "Chế độ 2 tràn sau 256 − F6H = 256 − 246 = 10 sự kiện, rồi tự nạp F6H nên cứ 10 sự kiện lại bật (bài tập 1)."}, {"q": "Bộ đếm đang chạy, chương trình đọc MOV A,TL0 rồi MOV B,TH0. Rủi ro là gì và sửa thế nào?", "o": ["TL0 có thể tràn sang TH0 giữa hai lệnh, ghép sai 256; đọc TH0, TL0 rồi so lại TH0", "Không có rủi ro vì đọc không làm thay đổi bộ đếm", "Đọc TL0 xóa cờ TF0; phải đọc TH0 trước", "MOV B,TH0 dừng bộ đếm 2 chu kỳ"], "a": 0, "e": "Hai byte được đọc ở hai thời điểm; nếu TL0 quay vòng ở giữa thì hai byte không khớp nhau (ví dụ 5). Đọc TH, TL, so lại TH và đọc lại nếu khác (ví dụ 6)."}]);

